const partial = "The reply was interrupted.";
const retry = () => {};

<Message from="assistant" status="error" onRetry={retry}>
  <Message.Content>{partial}</Message.Content>
</Message>

import { Copy } from "@phosphor-icons/react";

const reply = "Two files need updated imports.";

<Message
  from="assistant"
  actions={
    <IconButton variant="ghost" size="sm" aria-label="Copy reply">
      <Icon icon={Copy} size="sm" />
    </IconButton>
  }
>
  <Message.Content>{reply}</Message.Content>
</Message>
